List<Integer> nums = List.of(1, 2, 3, 4, 5, 6);
List<Integer> result = nums.stream()
    .filter(n -> n % 2 == 0)
    .map(n -> n * n)
    .collect(Collectors.toList());
System.out.println(result);

List<Integer> evalOrder = new ArrayList<>();
nums.stream()
    .filter(n -> { evalOrder.add(n); return n > 3; });
// 최종 연산 없음
System.out.println(evalOrder.isEmpty());
